const raw = $input.first().json;
const b = raw.body && Object.keys(raw.body).length ? raw.body : raw;
const topicId = String(b.topic_id ?? b.topicId ?? b.id ?? '').trim();
return [{ json: { topic_id: topicId, has_id: topicId ? 'yes' : 'no' } }];

const topic = $('取选题').first().json;
const srcs = $input.all().map(i => i.json);
let total = 0;
const parts = srcs.map((s, idx) => {
  const c = String(s.content ?? '').trim();
  if (c.length > 0) { total += c.length; return '【素材' + (idx + 1) + '】' + (s.title || s.url) + '\n' + c.slice(0, 6000); }
  return '【素材' + (idx + 1) + '】' + (s.title || s.url) + '\n（正文缺失，仅链接：' + s.url + '）';
});
const head = '选题：' + topic.title + '\n角度：' + (topic.angle || '未指定') + '\n方向：' + (topic.direction || '未指定') + '\n关键词：' + (topic.keywords || '无') + '\n补充说明：' + (topic.brief || '无');
const material = head + '\n\n' + parts.join('\n\n');
return [{ json: {
  topic_id: topic.topic_id,
  title: topic.title,
  angle: topic.angle || '',
  direction: topic.direction || '',
  keywords: topic.keywords || '',
  material,
  src_count: srcs.length,
  chars: total,
  enough_flag: total >= 200 ? 'yes' : 'no'
} }];

const m = $input.first().json;
const sys = '你是资深公众号主编。根据素材和给定角度产出文章提纲。只输出 JSON，不要任何解释或代码围栏。JSON 结构：{"title_options":["标题1","标题2","标题3"],"outline":[{"h2":"小节标题","points":["要点1","要点2"]}],"key_facts":["需要核对的硬事实"]}';
const user = '角度：' + m.angle + '\n方向：' + m.direction + '\n关键词：' + m.keywords + '\n\n素材：\n' + m.material;
const key = $('取密钥').first().json.value || '';
return [{ json: { api_key: key, request: { model: 'deepseek-flash', temperature: 0.6, messages: [ { role: 'system', content: sys }, { role: 'user', content: user } ] } } }];

const resp = $input.first().json;
const raw = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) ? resp.choices[0].message.content : '';
let outline = raw;
try { const clean = raw.replace(/```json/g, '').replace(/```/g, '').trim(); const o = JSON.parse(clean); outline = JSON.stringify(o); } catch (e) { outline = raw; }
const m = $('汇总原料').first().json;
return [{ json: { topic_id: m.topic_id, outline_raw: raw, outline_json: outline, material: m.material } }];

const d = $input.first().json;
const sys = '你是公众号资深作者。按提纲写成一篇可直接发布的成品稿。要求：结构完整、有独立观点、绝不编造数据（素材没有的信息宁可不写）、语言专业克制、不使用 emoji、字数 1500-2500。只输出 Markdown 正文，不要任何前缀说明。';
const user = '提纲：\n' + d.outline_json + '\n\n素材：\n' + d.material;
const key = $('取密钥').first().json.value || '';
return [{ json: { api_key: key, request: { model: 'deepseek-flash', temperature: 0.8, messages: [ { role: 'system', content: sys }, { role: 'user', content: user } ] } } }];

const resp = $input.first().json;
const md = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) ? resp.choices[0].message.content : '';
const esc = s => String(s ?? '').replace(/'/g, "''");
return [{ json: {
  topic_id: $('汇总原料').first().json.topic_id,
  outline: $('解析提纲').first().json.outline_json,
  body_md: md,
  outline_s: esc($('解析提纲').first().json.outline_json),
  body_md_s: esc(md),
  chars: md.length
} }];
